287	// renderCharts lints, renders and validates each chart. Without helm, every
288	// chart is reported as not rendered.
289	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
290		tool := v.opts.Helm
291		for _, chart := range charts {
292			if !available(tool) {
293				v.report.Unrendered = append(v.report.Unrendered, chart)
294				continue
295			}
296			lint := helmLint(ctx, v.scope, chart, tool)
297			v.report.Findings = append(v.report.Findings, lint...)
298	
299			cmd := helmArgs(v.scope, chart, tool, "template")
300			log.Printf("Running: %s", cmd)
301			rendered, err := runner.Run(ctx, cmd, nil)
302			if err != nil {
303				if ctx.Err() != nil {
304					return ctx.Err()
305				}
306				// helm lint renders the chart too, so a chart that does not
307				// render has usually been reported by it already, with more to
308				// say. The render failure is the fallback, not a second copy.
309				if !hasError(lint) {
310					v.report.Findings = append(v.report.Findings,
311						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", tool.Source, err))
312				}
313				continue
314			}
315			origins := helmOrigins(rendered, chart)
316			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
317				if file, ok := origins[kind+"/"+name]; ok {
318					return file
319				}
320				return chart
321			})
322			if err != nil {
323				return fmt.Errorf("chart %s: %w", chart, err)
324			}
325		}
326		return nil
327	}
