387	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
388	// when a chart fails; its messages are still the answer. A run that printed
389	// nothing parseable is logged and yields nothing — the render that follows
390	// will say whether the chart is usable.
391	func helmLint(ctx context.Context, scope renderScope, chart string, tool ToolSpec) []Finding {
392		cmd := helmArgs(scope, chart, tool, "lint")
393		log.Printf("Running: %s", cmd)
394		out, err := runner.Run(ctx, cmd, nil)
395		findings, recognised := parseHelmLint(out, chart, scope)
396		if err != nil && !recognised {
397			log.Printf("ERROR [scan/helm] lint %s: %v", chart, err)
398		}
399		return findings
400	}
