402	// parseHelmLint turns helm lint's text into findings. The second result says
403	// the output was helm lint's at all.
404	//
405	// A message's path is usually relative to the chart ("templates/cm.yaml"),
406	// but not always: the missing-dependency warning names the chart directory
407	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
408	// Both are brought back to a path relative to the target.
409	func parseHelmLint(out []byte, chart string, scope renderScope) ([]Finding, bool) {
410		file := func(p string) string { return helmLintPath(p, chart, scope) }
411		var findings []Finding
412		recognised := false
413		sc := bufio.NewScanner(bytes.NewReader(out))
414		for sc.Scan() {
415			line := strings.TrimSpace(sc.Text())
416			switch {
417			case strings.HasPrefix(line, "==> Linting"):
418				recognised = true
419			case strings.HasPrefix(line, "Error "):
420				// Printed instead of the messages when the chart could not be
421				// loaded at all.
422				recognised = true
423				findings = append(findings, helmLintFinding(chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
424			default:
425				m := helmLintLine.FindStringSubmatch(line)
426				if m == nil {
427					continue
428				}
429				recognised = true
430				switch m[1] {
431				case "ERROR":
432					findings = append(findings, helmLintFinding(file(m[2]), SeverityHigh, m[3]))
433				case "WARNING":
434					findings = append(findings, helmLintFinding(file(m[2]), SeverityLow, m[3]))
435				}
436			}
437		}
438		return findings, recognised
439	}
