96	// parseKubeconformOutput turns the report into findings, and counts the custom
97	// resources nobody could validate. read returns a manifest's content by the
98	// name kubeconform reported, to find the line a pointer designates; a file it
99	// cannot read keeps its findings, at line 0.
100	//
101	// origin, when not nil, names the file a resource came from — for rendered
102	// input, where kubeconform can only say "stdin".
103	func parseKubeconformOutput(out []byte, version string, read func(string) ([]byte, error), origin func(kind, name string) string) ([]Finding, int, error) {
104		var report kubeconformOutput
105		if err := json.Unmarshal(out, &report); err != nil {
106			return nil, 0, fmt.Errorf("parsing kubeconform output: %w", err)
107		}
108	
109		contents := map[string][]byte{}
110		content := func(name string) []byte {
111			if c, ok := contents[name]; ok {
112				return c
113			}
114			c, err := read(name)
115			if err != nil {
116				c = nil
117			}
118			contents[name] = c
119			return c
120		}
121	
122		var findings []Finding
123		skipped := 0
124		for _, r := range report.Resources {
125			if origin != nil {
126				r.Filename = origin(r.Kind, r.Name)
127			}
128			switch r.Status {
129			case kubeconformInvalid:
130				findings = append(findings, schemaFindings(r, content(r.Filename))...)
131			case kubeconformError:
132				f, custom := errorFinding(r, version, content(r.Filename))
133				if custom {
134					skipped++
135					continue
136				}
137				findings = append(findings, f)
138			}
139		}
140		return findings, skipped, nil
141	}
