165	// errorFinding classifies a resource kubeconform could not validate. The
166	// second result says it is a custom resource, which is skipped rather than
167	// reported: its schema is not missing, it lives somewhere kubeconform does not
168	// look.
169	func errorFinding(r kubeconformResource, version string, content []byte) (Finding, bool) {
170		if strings.HasPrefix(r.Msg, kubeconformMissingSchema) {
171			if !builtinGroups[apiGroup(r.Version)] {
172				return Finding{}, true
173			}
174			f := k8sFinding(r, K8sAPIRemovedID)
175			f.Title = fmt.Sprintf("%s: %s %s is not served by Kubernetes %s", resourceLabel(r), r.Version, r.Kind, version)
176			f.Description = "This apiVersion has been removed from the Kubernetes release the manifests are validated against: the API server would refuse the resource."
177			f.Message = r.Msg
178			f.Resolution = fmt.Sprintf("Migrate %s to an apiVersion Kubernetes %s serves; some migrations also change fields.", r.Kind, version)
179			f.References = []string{K8sDeprecationGuide}
180			if span, ok := k8s.DocumentField(content, r.Kind, r.Name, "apiVersion"); ok {
181				f.Line, f.EndLine = span.Line, span.EndLine
182			}
183			return f, false
184		}
185		f := k8sFinding(r, K8sParseID)
186		f.Title = "Cannot be read as a Kubernetes resource"
187		if r.Kind != "" {
188			f.Title = resourceLabel(r) + ": cannot be read as a Kubernetes resource"
189		}
190		f.Description = "kubeconform could not parse this document as a resource."
191		f.Message = r.Msg
192		f.Resolution = "Check the document's YAML syntax and that it carries apiVersion, kind and metadata."
193		return f, false
194	}
