104	// guidanceStatus is Manual when the finding tells how to fix it by hand, and
105	// No guidance available when it does not.
106	func guidanceStatus(f scan.Finding) fixStatus {
107		if hasGuidance(f) {
108			return fixStatus{State: fixManual}
109		}
110		return fixStatus{State: fixNoGuidance}
111	}
