216	// findingFilePath is the absolute path of the finding's file under the scanned
217	// directory, or the reason it cannot be opened. It does no I/O: whether the file
218	// exists is for the viewer to say (Rule 130, "Not knowing"). A path that leaves
219	// the target, by a parent segment or an absolute path elsewhere, is refused.
220	func findingFilePath(f scan.Finding, target string, onDisk bool) (string, shortcut.Availability) {
221		if !onDisk {
222			return "", shortcut.Unavailable(reasonFileNotOnDisk)
223		}
224		if f.File == "" {
225			return "", shortcut.Unavailable(reasonNoFile)
226		}
227		root := filepath.Clean(target)
228		file := filepath.ToSlash(f.File)
229		var path string
230		switch {
231		case file == scanMount || strings.HasPrefix(file, scanMount+"/"):
232			path = filepath.Join(root, filepath.FromSlash(strings.TrimPrefix(file, scanMount)))
233		case filepath.IsAbs(f.File):
234			path = filepath.Clean(f.File)
235		default:
236			path = filepath.Join(root, filepath.FromSlash(file))
237		}
238		rel, err := filepath.Rel(root, path)
239		if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
240			return "", shortcut.Unavailable(reasonFileOutsideTarget)
241		}
242		return path, shortcut.Availability{}
243	}
